const stages = [
  { key: 'received', area: 'raw', parentId: '1FRVcQkQdSWLY1ehdmw8hmatW2LypgKlA' },
  { key: 'processed', area: 'raw', parentId: '152tqJ3RF3hJ1hxOaqtlVYJC-Z5r_iHZT' },
  { key: 'approved', area: 'raw', parentId: '1gKuevsxdyiQBht8ymh_bHTK0MYlSZfLD' },
  { key: 'rejected', area: 'raw', parentId: '1761FZr7rHV863k_DDyqTfKpxwQanzmVa' },
  { key: 'aiApproved', area: 'content', parentId: '1O-kkEwshBXZ8AYVzPf6N7h0njySVri1V' },
  { key: 'aiRejected', area: 'content', parentId: '1d_koVEkklZh6DW9VzncvF8OfvOFAs3zU' },
  { key: 'creatorApproved', area: 'content', parentId: '1LQzu9HFblegSGbDCurmeYZ1OrNJwJp0c' },
  { key: 'creatorRejected', area: 'content', parentId: '1d2vIe5wh3ysjuvK0Q4tz0qZ16-HMl1DL' },
  { key: 'designerApproved', area: 'content', parentId: '1ivqifcaL0vr5nyLXn2P09yBGo2lqfUdQ' },
  { key: 'designerRejected', area: 'content', parentId: '14atX2ZW0zgz0yb2aV2OS4eMIgehG9CqP' },
];

const stageByParent = new Map(stages.map(stage => [stage.parentId, stage]));
const counts = Object.fromEntries(stages.map(stage => [stage.key, 0]));
const pieces = [];

for (const item of $input.all()) {
  const row = item.json;
  if (!row.id || !row.name) continue;

  const parents = Array.isArray(row.parents) ? row.parents : [];
  const stage = parents.map(parentId => stageByParent.get(parentId)).find(Boolean);
  if (!stage) continue;

  counts[stage.key] += 1;
  pieces.push({
    id: row.id,
    name: row.name,
    area: stage.area,
    stage: stage.key,
    updatedAt: row.modifiedTime ?? row.createdTime ?? null,
    driveUrl: row.webViewLink ?? `https://drive.google.com/drive/folders/${row.id}`,
  });
}

pieces.sort((a, b) => a.name.localeCompare(b.name));

return [{
  json: {
    generatedAt: new Date().toISOString(),
    counts,
    pieces,
  },
}];
